## Why This Question Is Asked
This question assesses your expertise in designing multi-tenant analytics architectures on Azure, a critical skill for building enterprise SaaS solutions and managed service offerings.

## Key Concepts Covered
- **Azure Lighthouse:** Enables delegated cross-tenant management, allowing service providers to manage tenant resources without requiring guest accounts
- **Hub-Spoke Topology:** Provides network isolation while sharing common services, with Private Endpoints ensuring all traffic traverses controlled paths
- **ADLS Gen2:** Offers tiered storage with hierarchical namespaces, ideal for tenant-specific data partitioning
- **Synapse Spark Pools:** Provides compute isolation per tenant with configurable node sizes and auto-scaling
- **Azure Purview:** Centralized data catalog with automated classification, sensitivity labels, and data lineage
- **Terraform + GitHub Actions:** Infrastructure-as-code approach ensuring reproducible deployments with automated testing and approval workflows
- **Azure Policy & Cost Management:** Enforces organizational tagging standards and provides budget alerts to prevent cost overruns

## Code Example
```hcl
# Main Terraform configuration for hub-spoke deployment

terraform {
  required_version = ">= 1.0"
  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 3.0"
    }
  }
}

provider "azurerm" {
  features {}
}

# Hub subscription variables
variable "hub_subscription_id" {
  description = "Hub subscription ID"
  type        = string
}

# Spoke subscription for tenant
variable "tenant_subscription_id" {
  description = "Tenant subscription ID"
  type        = string
}

# Hub network configuration
resource "azurerm_virtual_network" "hub_vnet" {
  name                = "hub-vnet"
  location            = "eastus"
  resource_group_name = "hub-rg"
  address_space       = ["10.0.0.0/16"]

  subnets {
    name           = "GatewaySubnet"
    address_prefix = "10.0.1.0/24"
  }

  subnets {
    name           = "AzureFirewallSubnet"
    address_prefix = "10.0.2.0/24"
  }

  subnets {
    name           = "PrivateEndpointSubnet"
    address_prefix = "10.0.3.0/24"
  }
}

# Spoke network configuration
resource "azurerm_virtual_network" "spoke_vnet" {
  name                = "tenant-spoke-vnet"
  location            = "eastus"
  resource_group_name = "tenant-rg"
  address_space       = ["10.1.0.0/16"]

  subnets {
    name           = "synapse-subnet"
    address_prefix = "10.1.1.0/24"
  }
}

# VNet peering from spoke to hub
resource "azurerm_virtual_network_peering" "spoke_to_hub" {
  name                      = "spoke-to-hub"
  resource_group_name       = "tenant-rg"
  virtual_network_name      = azurerm_virtual_network.spoke_vnet.name
  remote_virtual_network_id = azurerm_virtual_network.hub_vnet.id
  allow_forwarded_traffic   = true
}

# ADLS Gen2 with hierarchical namespaces
resource "azurerm_storage_account" "tenant_datalake" {
  name                      = "tenantdl${var.tenant_id}"
  resource_group_name       = "tenant-rg"
  location                  = "eastus"
  account_tier              = "Standard"
  account_replication_type  = "GRS"
  enable_hierarchical_namespace = true

  network_rules {
    default_action             = "Deny"
    virtual_network_subnet_ids = [azurerm_virtual_network.spoke_vnet.subnets[0].id]
  }
}

# Synapse Workspace
resource "azurerm_synapse_workspace" "tenant_workspace" {
  name                = "tenant-workspace-${var.tenant_id}"
  resource_group_name = "tenant-rg"
  location            = "eastus"
  storage_data_lake_gen2_filesystem_id = azurerm_storage_data_lake_gen2_tenant.fs.id
  sql_admin_login     = var.sql_admin_username
  sql_admin_password = var.sql_admin_password

  managed_virtual_network_enabled = true

  identity {
    type = "SystemAssigned"
  }
}

# Spark Pool for tenant
resource "azurerm_synapse_spark_pool" "tenant_spark" {
  name                  = "tenant-spark-pool"
  synapse_workspace_id  = azurerm_synapse_workspace.tenant_workspace.id
  node_size             = "Small"
  node_count            = 5
  auto_scale_enabled    = true
  min_node_count        = 3
  max_node_count        = 10

  spark_config {
    config = {
      "spark.dynamicAllocation.enabled" = "true"
      "spark.dynamicAllocation.minExecutors" = "1"
      "spark.dynamicAllocation.maxExecutors" = "2"
    }
  }

  tags = {
    Environment = "Production"
    TenantId    = var.tenant_id
    CostCenter  = var.cost_center
  }
}

# Azure Policy for required tagging
resource "azurerm_policy_definition" "require_tags" {
  name        = "require-tags"
  policy_type = "Custom"
  mode        = "Indexed"

  policy_rule = jsonencode({
    "if" : {
      "allOf" : [
        {
          "field" : "type",
          "equals" : "Microsoft.Storage/storageAccounts"
        },
        {
          "not" : {
            "field" : "tags",
            "containsKey" : "TenantId"
          }
        }
      ]
    },
    "then" : {
      "effect" : "deny"
    }
  })
}

# Cost Management Budget
resource "azurerm_cost_management_budget" "tenant_budget" {
  name            = "tenant-monthly-budget"
  scope           = var.tenant_subscription_id
  amount          = "1000"
  time_grain      = "Monthly"

  time_period {
    start_date = "2024-01-01T00:00:00Z"
    end_date   = "2024-12-31T00:00:00Z"
  }

  notification {
    threshold      = 80
    operator        = "GreaterThan"
    contact_emails = ["admin@tenant.com"]
  }
}

# Azure Lighthouse delegation
resource "azurerm_lighthouse_assignment" "tenant_delegation" {
  scope                   = var.tenant_subscription_id
  lighthouse_definition_id = var.lighthouse_definition_id

  authorization {
    principal_id = var.msp_principal_id
    role_definition_id = "4d97b98b-1d4f-4787-a291-c67834d212e7" # Contributor
  }
}

output "tenant_storage_endpoint" {
  value = azurerm_storage_account.tenant_datalake.primary_dfs_endpoint
}

output "tenant_synapse_endpoint" {
  value = azurerm_synapse_workspace.tenant_workspace.endpoint
}
```

## Implementation Best Practices

1. **Modular Design:** Create reusable Terraform modules for spokes that can be instantiated per tenant
2. **Automated Testing:** Integrate policy validation in CI/CD before deployment
3. **Monitoring:** Set up Azure Monitor alerts for budget thresholds and usage patterns
4. **Security:** Enable Microsoft Defender for Cloud and audit all Private Endpoint connections
5. **Data Partitioning:** Use tenant IDs as prefixes in container/blob naming for clear separation

This architecture provides strong tenant isolation while enabling centralized governance and efficient resource utilization across the multi-tenant environment.

